package ca.teamdman.sfm.gametest.tests.cable.tunnelled;

import ca.teamdman.sfm.common.capability.SFMWellKnownCapabilities;
import ca.teamdman.sfm.common.registry.registration.SFMBlocks;
import ca.teamdman.sfm.gametest.SFMGameTestDefinition;
import ca.teamdman.sfm.gametest.SFMGameTestGenerator;
import ca.teamdman.sfm.gametest.SFMGameTestGeneratorBase;
import ca.teamdman.sfm.gametest.SFMGameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.BarrelBlockEntity;
import net.minecraft.world.level.block.entity.FurnaceBlockEntity;
import net.neoforged.neoforge.capabilities.BlockCapabilityCache;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Exercises the position-cache relay, separately from directional forwarding.
 * Endpoint updates deliberately omit neighbour notifications: only the endpoint
 * position is invalidated, so the consumer cannot recover accidentally from a
 * notification at the tunnel itself. No optional compatibility mod is required.
 */
@SFMGameTestGenerator
public class TunnelledCapabilityCacheRecoveryGameTestGenerator extends SFMGameTestGeneratorBase {
    private static final BlockPos QUERY = new BlockPos(3, 2, 3);
    private record Probe(String name, Supplier<Block> tunnel) {}

    @Override
    public void generateTests(Consumer<SFMGameTestDefinition> tests) {
        for (Probe probe : List.of(
                new Probe("direct", null),
                new Probe("tunnelled_manager", SFMBlocks.TUNNELLED_MANAGER::get),
                new Probe("tunnelled_cable", SFMBlocks.TUNNELLED_CABLE::get),
                new Probe("tunnelled_cable_facade", SFMBlocks.TUNNELLED_CABLE_FACADE::get),
                new Probe("tunnelled_fancy_cable", SFMBlocks.TUNNELLED_FANCY_CABLE::get),
                new Probe("tunnelled_fancy_cable_facade", SFMBlocks.TUNNELLED_FANCY_CABLE_FACADE::get)
        )) {
            tests.accept(new RecoveryTest(probe));
        }
    }

    private static final class RecoveryTest extends SFMGameTestDefinition {
        private final Probe probe;

        private RecoveryTest(Probe probe) {
            this.probe = probe;
        }

        @Override
        public String template() {
            return "7x4x7";
        }

        @Override
        public String testName() {
            return probe.name + "_cached_provider_appearance_removal_replacement";
        }

        @Override
        public int maxTicks() {
            return 45;
        }

        @Override
        public void run(SFMGameTestHelper helper) {
            BlockPos endpoint = probe.tunnel == null ? QUERY : QUERY.east();
            helper.setBlock(endpoint, Blocks.AIR);
            if (probe.tunnel != null) {
                helper.setBlock(QUERY, probe.tunnel.get());
                if (probe.name.contains("facade")) {
                    helper.setFacade(QUERY, Blocks.GLOWSTONE.defaultBlockState());
                }
            }
            AtomicInteger endpointNotifications = new AtomicInteger();
            AtomicInteger queryNotifications = new AtomicInteger();
            var endpointCache = BlockCapabilityCache.create(
                    SFMWellKnownCapabilities.ITEM_HANDLER.capabilityKind(), helper.getLevel(),
                    helper.absolutePos(endpoint), Direction.WEST, () -> true,
                    endpointNotifications::incrementAndGet);
            var cache = BlockCapabilityCache.create(
                    SFMWellKnownCapabilities.ITEM_HANDLER.capabilityKind(), helper.getLevel(),
                    helper.absolutePos(QUERY), Direction.WEST, () -> true,
                    queryNotifications::incrementAndGet);

            helper.runAfterDelay(5, () -> {
                helper.assertTrue(endpointCache.getCapability() == null && cache.getCapability() == null,
                        "Both direct and queried endpoint caches must start absent");
                endpointNotifications.set(0);
                queryNotifications.set(0);
                helper.getLevel().setBlock(helper.absolutePos(endpoint), Blocks.BARREL.defaultBlockState(), 2);
                helper.getBlockEntity(endpoint, BarrelBlockEntity.class).setItem(0, new ItemStack(Items.COBBLESTONE, 12));
                helper.getLevel().invalidateCapabilities(helper.absolutePos(endpoint));
            });
            helper.runAfterDelay(10, () -> {
                helper.assertTrue(endpointNotifications.get() > 0 && queryNotifications.get() > 0,
                        "Cached absence was not invalidated at both endpoint and query positions");
                helper.assertTrue(endpointCache.getCapability() != null, "Direct provider control stayed absent");
                var capability = cache.getCapability();
                helper.assertTrue(capability != null, "Cached tunnel query stayed absent after provider appeared");
                var items = capability;
                helper.assertTrue(items.getStackInSlot(0).is(Items.COBBLESTONE)
                                && items.getStackInSlot(0).getCount() == 12,
                        "Recovered cached capability did not reach the live barrel");
            });
            helper.runAfterDelay(15, () -> {
                endpointCache.getCapability();
                cache.getCapability();
                endpointNotifications.set(0);
                queryNotifications.set(0);
                helper.getLevel().setBlock(helper.absolutePos(endpoint), Blocks.AIR.defaultBlockState(), 2);
                helper.getLevel().invalidateCapabilities(helper.absolutePos(endpoint));
            });
            helper.runAfterDelay(20, () -> {
                helper.assertTrue(endpointNotifications.get() > 0 && queryNotifications.get() > 0,
                        "Provider removal did not notify endpoint and queried tunnel positions");
                helper.assertTrue(endpointCache.getCapability() == null && cache.getCapability() == null,
                        "Removed provider left a stale cached capability");
            });
            helper.runAfterDelay(25, () -> {
                endpointNotifications.set(0);
                queryNotifications.set(0);
                helper.getLevel().setBlock(helper.absolutePos(endpoint), Blocks.FURNACE.defaultBlockState(), 2);
                helper.getBlockEntity(endpoint, FurnaceBlockEntity.class).setItem(1, new ItemStack(Items.COAL, 7));
                helper.getLevel().invalidateCapabilities(helper.absolutePos(endpoint));
            });
            helper.runAfterDelay(30, () -> {
                helper.assertTrue(endpointNotifications.get() > 0 && queryNotifications.get() > 0,
                        "Re-armed absent cache did not notify after a different provider appeared");
                helper.assertTrue(endpointCache.getCapability() != null, "Replacement direct control stayed absent");
                var capability = cache.getCapability();
                helper.assertTrue(capability != null, "Replacement did not restore the cached tunnel query");
                var items = capability;
                var direct = helper.getItemHandler(endpoint, Direction.WEST);
                helper.assertTrue(items.getSlots() == direct.getSlots() && items.getSlots() < 27,
                        "Replacement cache retained the old barrel handler");
                boolean foundFuel = false;
                for (int slot = 0; slot < direct.getSlots(); slot++) {
                    ItemStack expected = direct.getStackInSlot(slot);
                    ItemStack actual = items.getStackInSlot(slot);
                    helper.assertTrue((actual.isEmpty() && expected.isEmpty())
                                    || (actual.is(expected.getItem()) && actual.getCount() == expected.getCount()),
                            "Replacement cached capability disagrees with the live furnace at slot " + slot);
                    foundFuel |= actual.is(Items.COAL) && actual.getCount() == 7;
                }
                helper.assertTrue(foundFuel, "Replacement cached capability did not expose the live furnace fuel");
                helper.succeed();
            });
        }
    }
}
